package api

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// logoURLPrefix is the public URL path under which uploaded status-page logos
// are served. It is also the only prefix a stored logo_path may carry.
const logoURLPrefix = "/uploads/logos/"

// logoNameRe matches the server-generated file names. The client-supplied file
// name is never used, so anything not matching is a forgery or a stale path.
var logoNameRe = regexp.MustCompile(`^[0-9]+-[0-9a-f]{32}\.(png|jpg|webp)$`)

// logoContentTypes maps a stored extension to the Content-Type we serve it as.
// Serving never echoes a client-supplied type.
var logoContentTypes = map[string]string{".png": "image/png", ".jpg": "image/jpeg", ".webp": "image/webp"}

// logoExtForSniff maps a sniffed image type to the extension we store under.
// This lookup is the upload type gate: acceptance is decided here and nowhere
// else, never by the declared part Content-Type and never by the client file
// name. SVG is absent deliberately — logos are served same-origin with the
// session cookie, so a scriptable image type is not acceptable.
var logoExtForSniff = map[string]string{"image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp"}

// hexColorRe matches a normalised or shorthand CSS hex colour.
var hexColorRe = regexp.MustCompile(`^#([0-9a-f]{3}|[0-9a-f]{6})$`)

// LogoStore stores uploaded images as files in a single flat directory. Names
// are generated by the server, so nothing derived from a request ever reaches
// the filesystem unvalidated.
//
// One type serves two URL spaces — status-page logos and user avatars — because
// the name shape, the type gate and the traversal guard are identical for both.
// What differs is prefix, the public path the store issues and the only prefix
// it will act on, and dir. Both must differ together: two stores sharing a
// directory would share the ".upload-*" temp namespace, and Open would happily
// serve an avatar under the logo route, since logoNameRe matches either name.
type LogoStore struct {
	dir    string
	prefix string
}

// NewLogoStore creates dir when it does not exist and returns a store writing
// into it, issuing paths under logoURLPrefix.
func NewLogoStore(dir string) (*LogoStore, error) {
	return newUploadStore(dir, logoURLPrefix)
}

// NewAvatarStore is NewLogoStore for the avatar URL space. Point it at a
// directory of its own, never the logo directory.
func NewAvatarStore(dir string) (*LogoStore, error) {
	return newUploadStore(dir, avatarURLPrefix)
}

func newUploadStore(dir, prefix string) (*LogoStore, error) {
	clean := filepath.Clean(dir)
	// 0750, not 0755: nothing outside the app's own user and group has any
	// business listing the uploads directory, and internal/backup already
	// creates its dump directory that way. The files inside stay 0644 — they are
	// served to anonymous status-page visitors by this process, not read off
	// disk by anyone else.
	if err := os.MkdirAll(clean, 0o750); err != nil {
		return nil, fmt.Errorf("create uploads dir %q: %w", clean, err)
	}
	// os.MkdirAll returns nil for a directory that already exists WITHOUT
	// checking that it is writable, so an existing-but-unwritable bind mount
	// (the classic "chown /data/uploads to the app uid" deployment slip) sails
	// through here and only surfaces as an opaque 500 on the first real upload.
	// Probe write access once, now, at startup: a failure is returned to the
	// caller — which logs it loudly and leaves the endpoint answering a clear
	// 503 — instead of every upload failing silently per request. The probe file
	// never matches logoNameRe, so it is unservable even in the unlucky window
	// before it is removed.
	probe, err := os.CreateTemp(clean, ".probe-*")
	if err != nil {
		return nil, fmt.Errorf("uploads dir %q is not writable by the app user: %w", clean, err)
	}
	probeName := probe.Name()
	_ = probe.Close()
	_ = os.Remove(probeName)
	return &LogoStore{dir: clean, prefix: prefix}, nil
}

// Save writes data as a new file owned by ownerID and returns the public path to
// serve it under. The name carries 128 bits of entropy, so the URL is
// unguessable and safe to cache immutably. Data is written to a temp file and
// renamed into place, which is atomic within one directory: the serving route
// never observes a partially written file.
func (l *LogoStore) Save(ownerID int64, ext string, data []byte) (string, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	name := fmt.Sprintf("%d-%s%s", ownerID, hex.EncodeToString(raw[:]), ext)

	tmp, err := os.CreateTemp(l.dir, ".upload-*")
	if err != nil {
		return "", err
	}
	// Every failure between here and the rename must remove the temp file
	// rather than leave a stray .upload-* behind in the uploads directory.
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		_ = os.Remove(tmp.Name())
		return "", err
	}
	if err := tmp.Chmod(0o644); err != nil {
		_ = tmp.Close()
		_ = os.Remove(tmp.Name())
		return "", err
	}
	if err := tmp.Close(); err != nil {
		_ = os.Remove(tmp.Name())
		return "", err
	}
	if err := os.Rename(tmp.Name(), filepath.Join(l.dir, name)); err != nil {
		_ = os.Remove(tmp.Name())
		return "", err
	}
	return l.prefix + name, nil
}

// Remove deletes the file behind a public path this store issued. Paths from
// another URL space (including the other store's) and files that are already
// gone are ignored, so callers can treat cleanup as best-effort.
func (l *LogoStore) Remove(publicPath string) error {
	name, ok := strings.CutPrefix(publicPath, l.prefix)
	if !ok || !logoNameRe.MatchString(name) {
		return nil
	}
	// name matched logoNameRe two lines up, which admits only
	// "<digits>-<32 hex>.<png|jpg|webp>" — no separators, no dots, nothing that
	// can climb out of l.dir.
	if err := os.Remove(filepath.Join(l.dir, name)); err != nil && !errors.Is(err, fs.ErrNotExist) { //nolint:gosec // G703: name is regex-gated above
		return err
	}
	return nil
}

// Open opens a stored logo by file name for serving, along with its file info.
// name is matched against logoNameRe before it reaches the filesystem, so
// traversal segments, encoded separators and absolute paths all fall through
// to fs.ErrNotExist. Directories are rejected for the same reason. The caller
// closes the returned file.
func (l *LogoStore) Open(name string) (*os.File, fs.FileInfo, error) {
	if !logoNameRe.MatchString(name) {
		return nil, nil, fs.ErrNotExist
	}
	f, err := os.Open(filepath.Join(l.dir, name)) //nolint:gosec // G304: name is matched against logoNameRe on entry
	if err != nil {
		return nil, nil, err
	}
	info, err := f.Stat()
	if err != nil {
		_ = f.Close()
		return nil, nil, err
	}
	if info.IsDir() {
		_ = f.Close()
		return nil, nil, fs.ErrNotExist
	}
	return f, info, nil
}

// sanitizeLogoPath returns p when it is a path this server issued, else "".
// It is applied at the store boundary (scanStatusPage and hydratePage), because
// logo_path was free client text before the upload endpoints existed and rows
// already in the database may hold arbitrary URLs that the public page or the
// admin editor would otherwise interpolate into an <img src>. It is idempotent,
// so the explicit call on the public view stays a harmless restatement.
func sanitizeLogoPath(p string) string {
	p = strings.TrimSpace(p)
	if p == "" {
		return ""
	}
	name, ok := strings.CutPrefix(p, logoURLPrefix)
	if !ok || !logoNameRe.MatchString(name) {
		return ""
	}
	return p
}

// normalizeHexColor accepts #rgb or #rrggbb in any case and returns lowercase
// #rrggbb, or "" for anything else. The public page injects this value into an
// inline custom-property declaration, so nothing but a validated hex may pass.
func normalizeHexColor(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	if !hexColorRe.MatchString(s) {
		return ""
	}
	if len(s) == len("#rgb") {
		return string([]byte{'#', s[1], s[1], s[2], s[2], s[3], s[3]})
	}
	return s
}
